mapper.select:
SELECT s.store_id AS storeId, s.store_name AS storeName, i.ingredient_id AS ingredientId, i.ingredient_name AS ingredientName, COUNT(od.order_detail_id) AS totalOrderCount, COUNT(d.disposal_id) AS totalDisposalCount, COUNT(d.disposal_id) * 100.0 / NULLIF(COUNT(od.order_detail_id), 0) AS disposalRatePct FROM stores s JOIN orders o ON s.store_id = o.store_id JOIN order_details od ON o.order_id = od.order_id JOIN ingredients i ON od.ingredient_id = i.ingredient_id LEFT JOIN disposals d ON od.order_detail_id = d.order_detail_id AND d.disposal_status IN ('승인', '완료') WHERE od.order_status IN ('승인', '완료') AND s.store_id = #{storeId}
AND o.order_at >= #{startDate} AND o.order_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
GROUP BY storeId, ingredientId ORDER BY storeId, disposalRatePct DESC

SELECT i.ingredient_id AS ingredientId, i.ingredient_name AS ingredientName, SUM(d.disposal_price) AS totalDisposalPrice, SUM(d.disposal_quantity) AS totalDisposalQuantity FROM stores s JOIN orders o ON s.store_id = o.store_id JOIN order_details od ON o.order_id = od.order_id JOIN ingredients i ON od.ingredient_id = i.ingredient_id JOIN disposals d ON od.order_detail_id = d.order_detail_id AND d.disposal_status IN ('승인', '완료') WHERE od.order_status IN ('승인', '완료') AND s.store_id = #{storeId}
AND d.disposal_app_at >= #{startDate} AND d.disposal_app_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
GROUP BY s.store_id, ingredientId, ingredientName ORDER BY totalDisposalPrice DESC
